<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import CloudDirectoryCreate from './CloudDirectoryCreate.vue';
import type {CloudActionResult} from './cloud-files-types';
import CloudDirectorySearch from './CloudDirectorySearch.vue';
import {Folder,ArrowUp} from 'lucide-vue-next';
import {validCloudDirectory} from './cloud-files-route';
const props=defineProps<{initial:string;forbidden?:string[];disabled?:boolean;afterCreate?:()=>Promise<void>}>(),emit=defineEmits<{select:[string];close:[];busy:[boolean,string?,boolean?];confirmed:[CloudActionResult];unknown:[CloudActionResult];authenticationRequired:[]}>();
const searchOpen=ref(false),createOpen=ref(false),creationBusy=ref(false),createParent=ref('/');
function beginCreate(){if(!active||loading.value||creationBusy.value||props.disabled||error.value||forbidden(directory.value))return;searchOpen.value=false;createParent.value=directory.value;createOpen.value=true;}
function creationBusyChanged(value:boolean,label?:string,confirmed=false){creationBusy.value=value;emit('busy',value,label,confirmed);}
async function created(path:string){await props.afterCreate?.();const done=await load(path,0,true);if(done!==true)throw Error('新目录读取未确认');}
const directory=ref(validCloudDirectory(props.initial)?props.initial:'/'),draft=ref(directory.value),rows=ref<{fs_id:string;name:string;path:string}[]>([]),loading=ref(false),error=ref(''),offset=ref(0),next=ref<number|null>(null),observed=ref('');
const crumbs=computed(()=>[{name:'全部文件',path:'/'},...directory.value.split('/').filter(Boolean).map((name,index,parts)=>({name,path:'/'+parts.slice(0,index+1).join('/')}))]);
const boundaries=new Map<number,string>();let active=true,generation=0,controller:AbortController|undefined;
function forbidden(path:string){return (props.forbidden||[]).some(parent=>path===parent||path.startsWith(parent+'/'));}
async function load(path=directory.value,start=0,fromCreation=false){
 if(!active||props.disabled||loading.value||creationBusy.value&&!fromCreation)return;if(!validCloudDirectory(path)||forbidden(path)){error.value='目标无效，不能选择项目自身或其子目录';return;}
 searchOpen.value=false;const request=++generation;controller?.abort();controller=new AbortController();loading.value=true;draft.value=path;const q=new URLSearchParams({dir:path,offset:String(start),limit:'100',identity_format:'string'});
 if(start){const boundary=boundaries.get(start);if(!boundary){loading.value=false;error.value='缺少分页核对依据，请重新读取目录';return}q.set('expected_boundary',JSON.stringify({fingerprint:boundary}));}
 try{const response=await fetch('/api/cloud?'+q,{credentials:'same-origin',signal:controller.signal});if(request!==generation||!active)return;if(response.status===401){stop();emit('authenticationRequired');return}if(!response.ok)throw Error(await response.text()||'目标目录读取失败');const value=await response.json();if(request!==generation||!active)return;
 const changed=value.boundary_changed===true&&value.offset===0;
 if(value.directory!==path||value.offset!==(changed?0:start)||!Array.isArray(value.entries)||value.entries.length>100||value.entries.some((item:any)=>!item||typeof item.fs_id!=='string'||!/^[1-9][0-9]*$/.test(item.fs_id)||item.fs_id.length>19||BigInt(item.fs_id)>9223372036854775807n||typeof item.name!=='string'||!item.name||typeof item.directory!=='boolean'||!validCloudDirectory(item.path)||item.path!==(path==='/'?'':path)+'/'+item.name))throw Error('目标目录响应无效');
 const nextOffset=value.next_offset??null;if(nextOffset!==null&&(!Number.isSafeInteger(nextOffset)||nextOffset!==value.offset+value.entries.length||nextOffset<=value.offset||nextOffset>1000000||!value.next_boundary||typeof value.next_boundary.fingerprint!=='string'||!/^[a-f0-9]{64}$/.test(value.next_boundary.fingerprint)))throw Error('目标目录分页响应无效');
 if(new Set(value.entries.map((i:any)=>i.fs_id)).size!==value.entries.length)throw Error('目标目录身份重复，请刷新核对');
 if(start===0||changed)boundaries.clear();if(nextOffset!==null)boundaries.set(nextOffset,value.next_boundary.fingerprint);
 rows.value=value.entries.filter((item:any)=>item.directory);directory.value=path;offset.value=value.offset;next.value=nextOffset;observed.value=typeof value.observed_at_utc==='string'?value.observed_at_utc:'';error.value='';return true;
 }catch(e:any){if(request===generation&&active)error.value=(e.message||'目标目录读取失败')+'；上次结果不可选择。'}finally{if(request===generation)loading.value=false}
}
function parent(){const parts=directory.value.split('/').filter(Boolean);parts.pop();load('/'+parts.join('/'));}
function stop(){active=false;generation++;controller?.abort();loading.value=false;}
function resume(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;load()}}
watch(()=>props.disabled,value=>{if(value)stop()});onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',resume);load()});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',resume)});
</script>
<template><section class="cloud-directory-picker" data-testid="cloud-directory-picker" aria-label="选择目标网盘目录"><header class="page-header"><h3>选择目标目录</h3><button class="button secondary" type="button" :disabled="creationBusy" @click="emit('close')">取消选择</button></header><form @submit.prevent="load(draft)" class="picker-path"><button class="button secondary" type="button" :disabled="creationBusy||loading||disabled||directory==='/'" @click="parent"><ArrowUp :size="14"/>上一级</button><input v-model="draft" :disabled="creationBusy||loading||disabled" aria-label="目标浏览路径"/><button class="button secondary" :disabled="creationBusy||loading||disabled">打开</button></form><nav aria-label="目标目录路径" class="picker-crumbs"><button v-for="crumb in crumbs" :key="crumb.path" type="button" class="button secondary" :disabled="creationBusy||loading||disabled" @click="load(crumb.path)">{{crumb.name}}</button></nav><p>当前目录：{{directory}}</p><button type="button" class="button secondary" data-testid="cloud-picker-create-toggle" :disabled="creationBusy||loading||disabled||!!error||!active" @click="beginCreate">在此新建目录</button><CloudDirectoryCreate v-if="createOpen" :key="createParent" :directory="createParent" :after-success="created" @busy="creationBusyChanged" @confirmed="emit('confirmed',$event)" @close="createOpen=false" @unknown="emit('unknown',$event)" @authentication-required="emit('authenticationRequired')"/><button type="button" class="button secondary" data-testid="cloud-picker-search-toggle" :disabled="creationBusy||loading||disabled" @click="searchOpen=!searchOpen">{{searchOpen?'关闭目录搜索':'搜索已缓存目录'}}</button><CloudDirectorySearch v-if="searchOpen" :forbidden="props.forbidden" :disabled="creationBusy||loading||disabled" @navigate="load($event)" @close="searchOpen=false" @authentication-required="emit('authenticationRequired')"/><p v-if="loading" role="status">正在读取实时网盘目录…</p><p v-if="error" role="alert" class="notice danger">{{error}}</p><ul class="picker-directory-list"><li v-for="item in rows" :key="item.fs_id"><button class="button secondary" type="button" :disabled="creationBusy||loading||disabled||!!error||forbidden(item.path)" :title="forbidden(item.path)?'不能移入项目自身或子目录':item.path" @click="load(item.path)"><Folder :size="17"/>{{item.name}}</button></li></ul><p v-if="!loading&&!error&&!rows.length" class="muted">本页没有可浏览的文件夹{{next!==null?'，后面仍可能有目录':''}}。</p><div class="toolbar"><button class="button secondary" type="button" :disabled="creationBusy||loading||disabled||!!error||offset===0" @click="load(directory,Math.max(0,offset-100))">上一页</button><button class="button secondary" type="button" :disabled="creationBusy||loading||disabled||!!error||next===null" @click="load(directory,next!)">下一页</button><button class="button primary" type="button" data-testid="cloud-picker-use" :disabled="creationBusy||loading||disabled||!!error||!active||searchOpen||forbidden(directory)" @click="emit('select',directory)">使用此目录</button></div><small v-if="observed" class="muted">远端观察 UTC：{{observed}}</small></section></template>
<style scoped>.cloud-directory-picker{border:1px solid #c8d6ed;border-radius:10px;padding:16px;background:#f8faff;margin:12px 0}.picker-crumbs{display:flex;flex-wrap:wrap;gap:5px;margin-top:10px}.picker-crumbs .button{padding:4px 7px;min-height:28px}.picker-path{display:flex;flex-wrap:wrap;gap:8px}.picker-path input{flex:1;min-width:120px;border:1px solid #cbd5e5;border-radius:6px;padding:8px}.picker-directory-list{padding:0;list-style:none;max-height:260px;overflow:auto}.picker-directory-list li{margin:5px 0}.picker-directory-list .button{width:100%;justify-content:flex-start}.cloud-directory-picker h3{margin:0;font-size:15px}</style>
